good.code:
function pairSum(a, target) {
  let lo = 0, hi = a.length - 1
  while (lo < hi) {
    const sum = a[lo] + a[hi]
    if (sum === target) return [lo, hi]
    if (sum < target) lo++  // a[lo] is too small for every hi left
    else hi--               // a[hi] is too large for every lo left
  }
  return null
}

