function nextGreater(a) {
  const out = new Array(a.length).fill(-1)
  const stack = [] // indexes still waiting; their values decrease
  for (let i = 0; i < a.length; i++) {
    while (stack.length && a[stack[stack.length - 1]] < a[i]) out[stack.pop()] = a[i]
    stack.push(i)
  }
  return out
}
// nextGreater([2, 1, 2, 4, 3]) -> [4, 2, 4, -1, -1]

