  let left = 0, sum = 0, count = 0
  for (let right = 0; right < a.length; right++) {
    sum += a[right]
    while (sum > k && left <= right) sum -= a[left++]
    if (sum === k) count++
  }
  return count
}
// countSumK([1, -1, 1], 1) -> 2, but the answer is 3

