function countSumK(a, k) {
  const seen = new Map([[0, 1]]) // prefix sum -> times seen
  let prefix = 0, count = 0
  for (const x of a) {
    prefix += x
    count += seen.get(prefix - k) ?? 0
    seen.set(prefix, (seen.get(prefix) ?? 0) + 1)
  }
  return count
}
// countSumK([1, -1, 1], 1) -> 3

